import type * as THREE from "three";
import type {
  TransformObjectOptions,
  Vector3Optional,
} from "../types/object.types.js";

export class Helpers {
  static deg(v: number): number {
    return v;
  }

  static degToRad(v: number): number {
    return (v * Math.PI) / 180;
  }

  static rotationDegToRad(rot: { x: number; y: number; z: number }): {
    x: number;
    y: number;
    z: number;
  } {
    return {
      x: Helpers.degToRad(rot.x),
      y: Helpers.degToRad(rot.y),
      z: Helpers.degToRad(rot.z),
    };
  }

  static rotationDegToRadPartial(
    rot: Vector3Optional | undefined,
  ): Record<string, number> {
    const out: Record<string, number> = {};
    if (rot?.x != null) out.x = Helpers.degToRad(rot.x);
    if (rot?.y != null) out.y = Helpers.degToRad(rot.y);
    if (rot?.z != null) out.z = Helpers.degToRad(rot.z);
    return out;
  }

  static radToDeg(v: number): number {
    return (v * 180) / Math.PI;
  }

  static applyRotationDeg(
    target: THREE.Object3D,
    rotation: Vector3Optional | undefined,
  ): void {
    const resolved = Helpers.rotationDegToRad({
      x: rotation?.x ?? 0,
      y: rotation?.y ?? 0,
      z: rotation?.z ?? 0,
    });
    Helpers.assignVec3(target.rotation, resolved);
  }

  static applyTransform(
    target: THREE.Object3D,
    transform: TransformObjectOptions | undefined,
  ): void {
    target.position.set(
      transform?.position?.x ?? 0,
      transform?.position?.y ?? 0,
      transform?.position?.z ?? 0,
    );
    Helpers.applyRotationDeg(target, transform?.rotation);
    target.scale.set(
      transform?.scale?.x ?? 1,
      transform?.scale?.y ?? 1,
      transform?.scale?.z ?? 1,
    );
  }

  static readRotationDeg(
    target: THREE.Object3D | null | undefined,
  ): { x: number; y: number; z: number } {
    return {
      x: Helpers.radToDeg(target?.rotation.x ?? 0),
      y: Helpers.radToDeg(target?.rotation.y ?? 0),
      z: Helpers.radToDeg(target?.rotation.z ?? 0),
    };
  }

  static clamp(value: number, min: number, max: number): number {
    return Math.min(Math.max(value, min), max);
  }

  static clamp01(value: number): number {
    if (!Number.isFinite(value)) return 0;
    return Helpers.clamp(value, 0, 1);
  }

  static lerp(a: number, b: number, t: number): number {
    return a + (b - a) * t;
  }

  static lerpClamped(a: number, b: number, t: number): number {
    return Helpers.lerp(a, b, Helpers.clamp01(t));
  }

  static remap01(value: number, start: number, end: number): number {
    if (!Number.isFinite(value)) return 0;
    const range = end - start;
    if (range <= 0) return value >= end ? 1 : 0;
    return Helpers.clamp01((value - start) / range);
  }

  static assignVec3(
    target: { x: number; y: number; z: number },
    vars: { x?: number; y?: number; z?: number },
  ): void {
    if (vars.x != null) target.x = vars.x;
    if (vars.y != null) target.y = vars.y;
    if (vars.z != null) target.z = vars.z;
  }

  static assignRotationDeg(
    target: { x: number; y: number; z: number },
    vars: Vector3Optional | undefined,
  ): void {
    Helpers.assignVec3(target, Helpers.rotationDegToRadPartial(vars));
  }

  static hexToVec3(hex: string): number[] {
    const num = parseInt(hex.slice(1), 16);
    return [
      ((num / 65536) % 256) / 255,
      ((num / 256) % 256) / 255,
      (num % 256) / 255,
    ];
  }

  static hexToRgba(hex: string, alpha = 1): string {
    const r = parseInt(hex.slice(1, 3), 16);
    const g = parseInt(hex.slice(3, 5), 16);
    const b = parseInt(hex.slice(5, 7), 16);
    return `rgba(${r},${g},${b},${alpha})`;
  }

  static lightenHex(hex: string, amount: number): string {
    return [
      "#",
      ...[1, 3, 5].map((index) =>
        Math.min(255, parseInt(hex.slice(index, index + 2), 16) + amount)
          .toString(16)
          .padStart(2, "0"),
      ),
    ].join("");
  }


  static blendHexColors(hexA: string, hexB: string, t: number): number[] {
    const a = Helpers.hexToVec3(hexA);
    const b = Helpers.hexToVec3(hexB);
    return [
      a[0] + (b[0] - a[0]) * t,
      a[1] + (b[1] - a[1]) * t,
      a[2] + (b[2] - a[2]) * t,
    ];
  }

  static sanitizeImmediateVars(
    vars: Record<string, unknown>,
  ): Record<string, unknown> {
    const out: Record<string, unknown> = {};
    for (const [key, value] of Object.entries(vars)) {
      if (key === "duration" || key === "ease" || key === "delay") continue;
      out[key] = value;
    }
    return out;
  }

  static normalizeControlVars(
    vars: Record<string, unknown>,
  ): Record<string, unknown> {
    const next = { ...vars };
    const hasVisible = typeof next.visible === "boolean";
    const hasShow = typeof next.show === "boolean";
    const hasHide = typeof next.hide === "boolean";

    if (!hasVisible && hasShow) next.visible = next.show;
    if (!hasVisible && !hasShow && hasHide) next.visible = !(next.hide as boolean);

    delete next.show;
    delete next.hide;
    return next;
  }

  static debounce<T extends (...args: unknown[]) => void>(
    fn: T,
    ms: number,
  ): (...args: Parameters<T>) => void {
    let id: ReturnType<typeof setTimeout> | null = null;
    return (...args: Parameters<T>) => {
      if (id != null) clearTimeout(id);
      id = setTimeout(() => {
        fn(...args);
        id = null;
      }, ms);
    };
  }


  static throttle<T extends (...args: unknown[]) => void>(
    fn: T,
    ms: number,
  ): (...args: Parameters<T>) => void {
    let last = 0;
    return (...args: Parameters<T>) => {
      const now = Date.now();
      if (now - last < ms) return;
      last = now;
      fn(...args);
    };
  }
}

