70	class PhoneNumberFormatter {
71	  format(rawValue: string): string {
72	    const digits = this.toDigits(rawValue);
73	    if (digits === "") return "";
74	
75	    if (digits.startsWith("02")) {
76	      return this.formatSeoulNumber(digits);
