86	  private formatSeoulNumber(digits: string): string {
87	    if (digits.length <= 2) return digits;
88	    if (digits.length <= 5) return `${digits.slice(0, 2)}-${digits.slice(2)}`;
89	    if (digits.length <= 9) {
90	      return `${digits.slice(0, 2)}-${digits.slice(2, 5)}-${digits.slice(5)}`;
91	    }
92	    return `${digits.slice(0, 2)}-${digits.slice(2, 6)}-${digits.slice(6, 10)}`;
93	  }
