95	  private formatStandardNumber(digits: string): string {
96	    if (digits.length <= 3) return digits;
97	    if (digits.length <= 6) return `${digits.slice(0, 3)}-${digits.slice(3)}`;
98	    if (digits.length <= 10) {
99	      return `${digits.slice(0, 3)}-${digits.slice(3, 6)}-${digits.slice(6)}`;
100	    }
101	    return `${digits.slice(0, 3)}-${digits.slice(3, 7)}-${digits.slice(7, 11)}`;
102	  }
