476	      this.view.render(group.root, group.validator.validate());
477	      this.syncProjectGroup(target);
478	      return;
479	    }
480	
481	    const single = this.singleByInput.get(target);
482	    if (single) this.view.render(single.root, single.validator.validate());
483	    this.syncProjectGroup(target);
484	  }
