486	  private onFocusOut(event: FocusEvent): void {
487	    const target = event.target;
488	    if (
489	      !(
490	        target instanceof HTMLInputElement ||
491	        target instanceof HTMLTextAreaElement
492	      )
493	    )
494	      return;
495	
496	    const single = this.singleByInput.get(target);
497	    if (!single || !this.isTextLike(single.input)) return;
