511	    if (project.inputs.some((input) => input === target)) return;
512	    this.view.render(project.root, project.validator.validate());
513	  }
514	
515	  private validateAll(): boolean {
516	    const groupResults = this.groups.map((group) => {
517	      group.touched = true;
518	      const result = group.validator.validate();
519	      this.view.render(group.root, result);
520	      return result.valid;
521	    });
522	    const singleResults = this.singles.map((single) => {
523	      const result = single.validator.validate();
524	      this.view.render(single.root, result);
525	      return result.valid;
526	    });
527	    return groupResults.every(Boolean) && singleResults.every(Boolean);
528	  }
