530	  private focusFirstInvalid(): void {
531	    const invalidGroup = this.groups.find((g) => !g.validator.validate().valid);
532	    if (invalidGroup) {
533	      invalidGroup.inputs[0]?.focus();
534	      return;
535	    }
536	
537	    const invalidSingle = this.singles.find(
538	      (s) => !s.validator.validate().valid,
539	    );
540	    invalidSingle?.input.focus();
541	  }
542	
543	  private isTextLike(input: HTMLInputElement | HTMLTextAreaElement): boolean {
544	    if (input instanceof HTMLTextAreaElement) return true;
545	    return !TEXTLIKE_SKIP_INPUT_TYPES.has(input.type);
546	  }
