553	
554	  private syncPhoneInput(target: HTMLInputElement | HTMLTextAreaElement): void {
555	    if (!(target instanceof HTMLInputElement)) return;
556	    if (target.name !== "phone") return;
557	    this.applyPhoneFormat(target);
558	  }
559	
560	  private applyPhoneFormat(input: HTMLInputElement): void {
561	    const formattedValue = this.phoneFormatter.format(input.value);
562	    if (input.value === formattedValue) return;
563	    input.value = formattedValue;
564	  }
565	}
