571	    const errorClass = options.errorClass ?? "no-form-error";
572	    const form = root.querySelector<HTMLFormElement>(formSelector);
573	    if (!form) return;
574	
575	    const view = new ValidationMessageView(errorClass);
576	    new ContactFormController(form, view).mount();
577	  }
