import { Debounce } from "../utils/Debounce.js";
import { dispatchInputChange } from "../utils/domUtil.js";
import type {
  AttachmentElements,
  ContactFormValidationOptions,
  FieldValidator,
  GroupValidation,
  SingleValidation,
  ValidationResult,
} from "../types/component.types.js";

const INPUT_DEBOUNCE_MS = 200;
const TEXTLIKE_SKIP_INPUT_TYPES = new Set(["checkbox", "radio", "file"]);

class SelectionGroupValidator implements FieldValidator {
  constructor(
    private readonly inputs: HTMLInputElement[],
    private readonly message: string,
  ) {}

  validate(): ValidationResult {
    return this.inputs.some((i) => i.checked)
      ? { valid: true }
      : { valid: false, message: this.message };
  }
}

class RequiredValueValidator implements FieldValidator {
  constructor(
    private readonly input: HTMLInputElement | HTMLTextAreaElement,
    private readonly message: string,
  ) {}

  validate(): ValidationResult {
    if (this.input.disabled) return { valid: true };
    return this.input.value.trim() !== ""
      ? { valid: true }
      : { valid: false, message: this.message };
  }
}

class RequiredCheckedValidator implements FieldValidator {
  constructor(
    private readonly input: HTMLInputElement,
    private readonly message: string,
  ) {}

  validate(): ValidationResult {
    return this.input.checked
      ? { valid: true }
      : { valid: false, message: this.message };
  }
}

class OptionalFormatValidator implements FieldValidator {
  constructor(
    private readonly input: HTMLInputElement,
    private readonly message: string,
  ) {}

  validate(): ValidationResult {
    const value = this.input.value.trim();
    if (value === "") return { valid: true };
    return this.input.validity.valid
      ? { valid: true }
      : { valid: false, message: this.message };
  }
}

class PhoneNumberFormatter {
  format(rawValue: string): string {
    const digits = this.toDigits(rawValue);
    if (digits === "") return "";

    if (digits.startsWith("02")) {
      return this.formatSeoulNumber(digits);
    }

    return this.formatStandardNumber(digits);
  }

  toDigits(rawValue: string): string {
    return rawValue.replace(/\D/g, "").slice(0, 11);
  }

  private formatSeoulNumber(digits: string): string {
    if (digits.length <= 2) return digits;
    if (digits.length <= 5) return `${digits.slice(0, 2)}-${digits.slice(2)}`;
    if (digits.length <= 9) {
      return `${digits.slice(0, 2)}-${digits.slice(2, 5)}-${digits.slice(5)}`;
    }
    return `${digits.slice(0, 2)}-${digits.slice(2, 6)}-${digits.slice(6, 10)}`;
  }

  private formatStandardNumber(digits: string): string {
    if (digits.length <= 3) return digits;
    if (digits.length <= 6) return `${digits.slice(0, 3)}-${digits.slice(3)}`;
    if (digits.length <= 10) {
      return `${digits.slice(0, 3)}-${digits.slice(3, 6)}-${digits.slice(6)}`;
    }
    return `${digits.slice(0, 3)}-${digits.slice(3, 7)}-${digits.slice(7, 11)}`;
  }
}

class PhoneNumberValidator implements FieldValidator {
  constructor(
    private readonly input: HTMLInputElement,
    private readonly message: string,
    private readonly formatter: PhoneNumberFormatter,
  ) {}

  validate(): ValidationResult {
    const digits = this.formatter.toDigits(this.input.value);
    if (digits === "") {
      return { valid: false, message: this.message };
    }

    if (digits.startsWith("02")) {
      return digits.length === 9 || digits.length === 10
        ? { valid: true }
        : { valid: false, message: this.message };
    }

    if (!digits.startsWith("0")) {
      return { valid: false, message: this.message };
    }

    return digits.length === 10 || digits.length === 11
      ? { valid: true }
      : { valid: false, message: this.message };
  }
}

class ValidationMessageView {
  constructor(private readonly errorClass: string) {}

  render(container: HTMLElement, result: ValidationResult): void {
    const node = this.resolveErrorNode(container);
    node.hidden = false;

    if (result.valid) {
      node.textContent = "\u00A0";
      node.classList.add("is-empty");
      return;
    }

    node.textContent = result.message ?? "";
    node.classList.remove("is-empty");
  }

  ensure(container: HTMLElement): void {
    const node = this.resolveErrorNode(container);
    node.hidden = false;
    if (node.textContent?.trim()) return;
    node.textContent = "\u00A0";
    node.classList.add("is-empty");
  }

  private resolveErrorNode(container: HTMLElement): HTMLElement {
    const host = this.resolveHost(container);
    const existing = host.querySelector<HTMLElement>(
      `:scope > .${this.errorClass}`,
    );
    if (existing) {
      existing.hidden = false;
      return existing;
    }

    const node = document.createElement("p");
    node.className = `${this.errorClass} f-body-3 --regular`;
    node.hidden = false;
    host.appendChild(node);
    return node;
  }

  private resolveHost(container: HTMLElement): HTMLElement {
    return (
      container.querySelector<HTMLElement>(":scope > .no-form-wrap") ??
      container
    );
  }
}

class AttachmentUiController {
  constructor(private readonly form: HTMLFormElement) {}

  mount(): void {
    const elements = this.resolveElements();
    if (!elements) return;

    const sync = (): void => this.syncUi(elements);

    elements.input.addEventListener("change", sync);
    elements.clearButton.addEventListener("click", (event) => {
      event.preventDefault();
      elements.input.value = "";
      sync();
      dispatchInputChange(elements.input);
    });

    sync();
  }

  private resolveElements(): AttachmentElements | null {
    const input = this.form.querySelector<HTMLInputElement>(
      'input[name="attachment"]',
    );
    const placeholder = this.form.querySelector<HTMLElement>(
      ".no-form-file-placeholder",
    );
    const clearButton = this.form.querySelector<HTMLButtonElement>(
      ".no-form-file-clear",
    );
    if (!input || !placeholder || !clearButton) return null;
    return {
      input,
      placeholder,
      clearButton,
      defaultText: placeholder.textContent ?? "",
    };
  }

  private syncUi(elements: AttachmentElements): void {
    const fileName = elements.input.files?.[0]?.name ?? "";

    if (fileName !== "") {
      elements.placeholder.textContent = fileName;
      elements.placeholder.title = fileName;
      elements.clearButton.hidden = false;
      return;
    }

    elements.placeholder.textContent = elements.defaultText;
    elements.placeholder.removeAttribute("title");
    elements.clearButton.hidden = true;
  }
}

class ProjectOtherUiController {
  constructor(private readonly form: HTMLFormElement) {}

  mount(): void {
    const trigger = this.form.querySelector<HTMLInputElement>(
      "[data-project-other-toggle]",
    );
    const panel = this.form.querySelector<HTMLElement>("[data-project-other-panel]");
    const input = this.form.querySelector<HTMLInputElement>("[data-project-other-input]");

    if (!trigger || !panel || !input) return;

    const sync = (): void => {
      const isActive = trigger.checked;
      panel.classList.toggle("is-active", isActive);
      panel.setAttribute("aria-hidden", isActive ? "false" : "true");
      input.disabled = !isActive;
      input.toggleAttribute("required", isActive);

      if (!isActive) {
        input.setCustomValidity("");
        const errorNode = input
          .closest<HTMLElement>(".no-form-field")
          ?.querySelector<HTMLElement>(".no-form-error");
        if (errorNode) {
          errorNode.textContent = "\u00A0";
          errorNode.classList.add("is-empty");
        }
      }
    };

    trigger.addEventListener("change", sync);
    sync();
  }
}

class ContactFormController {
  private readonly groups: GroupValidation[] = [];
  private readonly singles: SingleValidation[] = [];
  private readonly groupByInput = new Map<HTMLInputElement, GroupValidation>();
  private readonly groupByKey = new Map<string, GroupValidation>();
  private readonly singleByInput = new Map<
    HTMLInputElement | HTMLTextAreaElement,
    SingleValidation
  >();
  private readonly attachmentUi: AttachmentUiController;
  private readonly projectOtherUi: ProjectOtherUiController;
  private readonly phoneFormatter: PhoneNumberFormatter;
  private readonly _inputDebounce: Debounce;
  private _lastInputTarget: HTMLInputElement | HTMLTextAreaElement | null =
    null;

  constructor(
    private readonly form: HTMLFormElement,
    private readonly view: ValidationMessageView,
  ) {
    this.attachmentUi = new AttachmentUiController(form);
    this.projectOtherUi = new ProjectOtherUiController(form);
    this.phoneFormatter = new PhoneNumberFormatter();
    this._inputDebounce = new Debounce(INPUT_DEBOUNCE_MS);
  }

  mount(): void {
    if (this.form.dataset.formValidationBound === "true") return;
    this.form.dataset.formValidationBound = "true";

    this.setupGroups();
    this.setupSingles();
    this.attachmentUi.mount();
    this.projectOtherUi.mount();
    this.mountPhoneFormatter();
    this.primeErrorSlots();

    this.form.addEventListener("submit", (e) => this.onSubmit(e));
    this.form.addEventListener("input", (e) => this.onInput(e));
    this.form.addEventListener("change", (e) => this.onChange(e));
    this.form.addEventListener("focusout", (e) => this.onFocusOut(e));
  }

  private primeErrorSlots(): void {
    this.groups.forEach((g) => this.view.ensure(g.root));
    this.singles.forEach((s) => this.view.ensure(s.root));
  }

  private setupGroups(): void {
    this.addGroup(
      "project",
      'input[name="project[]"]',
      "프로젝트 유형을 1개 이상 선택해 주세요.",
    );
    this.addGroup(
      "service",
      'input[name="service[]"]',
      "서비스를 1개 이상 선택해 주세요.",
    );
    this.addGroup(
      "budget",
      'input[name="budget"]',
      "프로젝트 예산을 선택해 주세요.",
    );
    this.addGroup(
      "period",
      'input[name="period"]',
      "프로젝트 예상 일정을 선택해 주세요.",
    );
  }

  private setupSingles(): void {
    this.addRequired("project_other", "기타 프로젝트를 입력해 주세요.");
    this.addRequired("company", "회사명을 입력해 주세요.");
    this.addRequired("name", "이름을 입력해 주세요.");
    this.addRequired(
      "position",
      "부서 또는 직책을 입력해 주세요.",
    );
    this.addPhone("phone", "연락처 형식을 확인해 주세요.");
    this.addRequired("detail", "상세 내용을 입력해 주세요.");
    this.addFormat("email", "이메일 형식을 확인해 주세요.");
    this.addFormat(
      "homepage",
      "홈페이지 주소 형식을 확인해 주세요.",
    );

    const privacy = this.form.querySelector<HTMLInputElement>(
      'input[name="agree_privacy"]',
    );
    const root =
      privacy?.closest<HTMLElement>(".no-form-field") ??
      privacy?.closest<HTMLElement>(".no-form-group");
    if (!privacy || !root) return;

    this.registerSingle({
      key: "agree-privacy",
      root,
      input: privacy,
      validator: new RequiredCheckedValidator(privacy, "개인정보 처리방침에 동의해 주세요."),
    });
  }

  private addGroup(key: string, selector: string, message: string): void {
    const inputs = Array.from(
      this.form.querySelectorAll<HTMLInputElement>(selector),
    );
    if (inputs.length === 0) return;

    const root = inputs[0]?.closest<HTMLElement>(".no-form-group");
    if (!root) return;

    const group: GroupValidation = {
      key,
      root,
      inputs,
      validator: new SelectionGroupValidator(inputs, message),
      touched: false,
    };

    this.groups.push(group);
    this.groupByKey.set(key, group);
    inputs.forEach((input) => this.groupByInput.set(input, group));
  }

  private addRequired(name: string, message: string): void {
    const input = this.form.querySelector<
      HTMLInputElement | HTMLTextAreaElement
    >(`[name="${name}"]`);
    const root = input?.closest<HTMLElement>(".no-form-field");
    if (!input || !root) return;

    this.registerSingle({
      key: name,
      root,
      input,
      validator: new RequiredValueValidator(input, message),
    });
  }

  private addPhone(name: string, message: string): void {
    const input = this.form.querySelector<HTMLInputElement>(`[name="${name}"]`);
    const root = input?.closest<HTMLElement>(".no-form-field");
    if (!input || !root) return;

    this.registerSingle({
      key: name,
      root,
      input,
      validator: new PhoneNumberValidator(input, message, this.phoneFormatter),
    });
  }

  private addFormat(name: string, message: string): void {
    const input = this.form.querySelector<HTMLInputElement>(`[name="${name}"]`);
    const root = input?.closest<HTMLElement>(".no-form-field");
    if (!input || !root) return;

    this.registerSingle({
      key: name,
      root,
      input,
      validator: new OptionalFormatValidator(input, message),
    });
  }

  private registerSingle(single: SingleValidation): void {
    this.singles.push(single);
    this.singleByInput.set(single.input, single);
  }

  private onSubmit(event: Event): void {
    if (this.validateAll()) return;
    event.preventDefault();
    this.focusFirstInvalid();
  }

  private onInput(event: Event): void {
    const target = event.target;
    if (
      !(
        target instanceof HTMLInputElement ||
        target instanceof HTMLTextAreaElement
      )
    )
      return;
    this.syncPhoneInput(target);
    this._lastInputTarget = target;
    this._inputDebounce.runDebounce(() => {
      if (this._lastInputTarget) this.syncSingle(this._lastInputTarget);
      this._lastInputTarget = null;
    });
  }

  private onChange(event: Event): void {
    const target = event.target;
    if (!(target instanceof HTMLInputElement)) return;

    const group = this.groupByInput.get(target);
    if (group) {
      group.touched = true;
      this.view.render(group.root, group.validator.validate());
      this.syncProjectGroup(target);
      return;
    }

    const single = this.singleByInput.get(target);
    if (single) this.view.render(single.root, single.validator.validate());
    this.syncProjectGroup(target);
  }

  private onFocusOut(event: FocusEvent): void {
    const target = event.target;
    if (
      !(
        target instanceof HTMLInputElement ||
        target instanceof HTMLTextAreaElement
      )
    )
      return;

    const single = this.singleByInput.get(target);
    if (!single || !this.isTextLike(single.input)) return;

    this.view.render(single.root, single.validator.validate());
  }

  private syncSingle(target: HTMLInputElement | HTMLTextAreaElement): void {
    const single = this.singleByInput.get(target);
    if (single) this.view.render(single.root, single.validator.validate());
    this.syncProjectGroup(target);
  }

  private syncProjectGroup(target: HTMLElement): void {
    const project = this.groupByKey.get("project");
    if (!project?.touched) return;
    if (project.inputs.some((input) => input === target)) return;
    this.view.render(project.root, project.validator.validate());
  }

  private validateAll(): boolean {
    const groupResults = this.groups.map((group) => {
      group.touched = true;
      const result = group.validator.validate();
      this.view.render(group.root, result);
      return result.valid;
    });
    const singleResults = this.singles.map((single) => {
      const result = single.validator.validate();
      this.view.render(single.root, result);
      return result.valid;
    });
    return groupResults.every(Boolean) && singleResults.every(Boolean);
  }

  private focusFirstInvalid(): void {
    const invalidGroup = this.groups.find((g) => !g.validator.validate().valid);
    if (invalidGroup) {
      invalidGroup.inputs[0]?.focus();
      return;
    }

    const invalidSingle = this.singles.find(
      (s) => !s.validator.validate().valid,
    );
    invalidSingle?.input.focus();
  }

  private isTextLike(input: HTMLInputElement | HTMLTextAreaElement): boolean {
    if (input instanceof HTMLTextAreaElement) return true;
    return !TEXTLIKE_SKIP_INPUT_TYPES.has(input.type);
  }

  private mountPhoneFormatter(): void {
    const phoneInput = this.form.querySelector<HTMLInputElement>('input[name="phone"]');
    if (!phoneInput) return;
    this.applyPhoneFormat(phoneInput);
  }

  private syncPhoneInput(target: HTMLInputElement | HTMLTextAreaElement): void {
    if (!(target instanceof HTMLInputElement)) return;
    if (target.name !== "phone") return;
    this.applyPhoneFormat(target);
  }

  private applyPhoneFormat(input: HTMLInputElement): void {
    const formattedValue = this.phoneFormatter.format(input.value);
    if (input.value === formattedValue) return;
    input.value = formattedValue;
  }
}

export class ContactFormValidation {
  static init(options: ContactFormValidationOptions = {}): void {
    const root = options.root ?? document;
    const formSelector = options.formSelector ?? ".no-sub-contact form";
    const errorClass = options.errorClass ?? "no-form-error";
    const form = root.querySelector<HTMLFormElement>(formSelector);
    if (!form) return;

    const view = new ValidationMessageView(errorClass);
    new ContactFormController(form, view).mount();
  }
}

